-- Historical baseline for fresh PLT installations. This is intentionally a
-- schema-only migration: seed data remains in prisma/seed.ts. Phase 6
-- additions are kept in their existing additive migrations below.

CREATE TYPE "UserRole" AS ENUM ('USER', 'ADMIN');
CREATE TYPE "UserStatus" AS ENUM ('ACTIVE', 'SUSPENDED', 'DEACTIVATED');
CREATE TYPE "KycStatus" AS ENUM ('NOT_STARTED', 'PENDING', 'VERIFIED', 'REJECTED');
CREATE TYPE "VerificationTokenType" AS ENUM ('EMAIL_VERIFICATION', 'PASSWORD_RESET');
CREATE TYPE "AssetType" AS ENUM ('FIAT', 'CRYPTO');
CREATE TYPE "BankAccountType" AS ENUM ('CURRENT', 'SAVINGS', 'FOREIGN_CURRENCY', 'FIXED_DEPOSIT');
CREATE TYPE "BeneficiaryType" AS ENUM ('INTERNAL_PLT', 'EXTERNAL_BANK');
CREATE TYPE "TransferStatus" AS ENUM ('PENDING', 'COMPLETED', 'FAILED', 'REVERSED');
CREATE TYPE "TransactionType" AS ENUM ('TRANSFER', 'DEPOSIT', 'WITHDRAWAL', 'TRADE', 'CONVERSION', 'FEE', 'CARD_PAYMENT');
CREATE TYPE "TransactionDirection" AS ENUM ('CREDIT', 'DEBIT');
CREATE TYPE "TransactionStatus" AS ENUM ('PENDING', 'COMPLETED', 'FAILED', 'REVERSED');
CREATE TYPE "LedgerAccountType" AS ENUM ('ASSET', 'LIABILITY', 'EQUITY', 'REVENUE', 'EXPENSE');
CREATE TYPE "LedgerDirection" AS ENUM ('DEBIT', 'CREDIT');
CREATE TYPE "OrderSide" AS ENUM ('BUY', 'SELL');
CREATE TYPE "OrderType" AS ENUM ('MARKET', 'LIMIT');
CREATE TYPE "OrderStatus" AS ENUM ('OPEN', 'FILLED', 'PARTIALLY_FILLED', 'CANCELLED', 'REJECTED');
CREATE TYPE "DepositStatus" AS ENUM ('PENDING', 'COMPLETED', 'FAILED');
CREATE TYPE "WithdrawalStatus" AS ENUM ('PENDING', 'REVIEWING', 'APPROVED', 'REJECTED', 'COMPLETED');
CREATE TYPE "CardFormFactor" AS ENUM ('PHYSICAL', 'VIRTUAL');
CREATE TYPE "CardStatus" AS ENUM ('ACTIVE', 'FROZEN', 'LOST', 'CANCELLED');
CREATE TYPE "NotificationType" AS ENUM ('SECURITY', 'TRANSACTION', 'MARKETING', 'SYSTEM');

CREATE TABLE "users" ("id" TEXT NOT NULL, "email" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "role" "UserRole" NOT NULL DEFAULT 'USER', "status" "UserStatus" NOT NULL DEFAULT 'ACTIVE', "emailVerifiedAt" TIMESTAMP(3), "phoneVerifiedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "users_pkey" PRIMARY KEY ("id"));
CREATE TABLE "profiles" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "fullName" TEXT NOT NULL, "country" TEXT, "preferredFiatCurrency" TEXT NOT NULL DEFAULT 'USD', "accountType" TEXT NOT NULL DEFAULT 'individual', "dateOfBirth" TIMESTAMP(3), "phoneNumber" TEXT, "kycStatus" "KycStatus" NOT NULL DEFAULT 'NOT_STARTED', "onboardingCompletedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "profiles_pkey" PRIMARY KEY ("id"));
CREATE TABLE "security_settings" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "mfaEnabled" BOOLEAN NOT NULL DEFAULT false, "mfaSecretEncrypted" TEXT, "transactionPinHash" TEXT, "antiPhishingPhrase" TEXT, "withdrawalAllowlistEnabled" BOOLEAN NOT NULL DEFAULT false, "biometricEnabled" BOOLEAN NOT NULL DEFAULT false, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "security_settings_pkey" PRIMARY KEY ("id"));
CREATE TABLE "sessions" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "sessionTokenHash" TEXT NOT NULL, "ipAddress" TEXT, "userAgent" TEXT, "expiresAt" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "sessions_pkey" PRIMARY KEY ("id"));
CREATE TABLE "verification_tokens" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "tokenHash" TEXT NOT NULL, "type" "VerificationTokenType" NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "consumedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "verification_tokens_pkey" PRIMARY KEY ("id"));
CREATE TABLE "trusted_devices" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "deviceFingerprint" TEXT NOT NULL, "deviceName" TEXT, "trusted" BOOLEAN NOT NULL DEFAULT false, "lastSeenAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "trusted_devices_pkey" PRIMARY KEY ("id"));
CREATE TABLE "login_events" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "ipAddress" TEXT, "userAgent" TEXT, "success" BOOLEAN NOT NULL, "riskFlag" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "login_events_pkey" PRIMARY KEY ("id"));
CREATE TABLE "assets" ("id" TEXT NOT NULL, "symbol" TEXT NOT NULL, "name" TEXT NOT NULL, "type" "AssetType" NOT NULL, "precision" INTEGER NOT NULL, "isActive" BOOLEAN NOT NULL DEFAULT true, "iconUrl" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "assets_pkey" PRIMARY KEY ("id"));
CREATE TABLE "bank_accounts" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "type" "BankAccountType" NOT NULL, "currencySymbol" TEXT NOT NULL, "accountNumber" TEXT NOT NULL, "nickname" TEXT, "balanceCache" DECIMAL(36,18) NOT NULL DEFAULT 0, "isPrimary" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "bank_accounts_pkey" PRIMARY KEY ("id"));
CREATE TABLE "crypto_wallets" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "label" TEXT NOT NULL DEFAULT 'Spot Wallet', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "crypto_wallets_pkey" PRIMARY KEY ("id"));
CREATE TABLE "asset_balances" ("id" TEXT NOT NULL, "walletId" TEXT NOT NULL, "assetSymbol" TEXT NOT NULL, "available" DECIMAL(36,18) NOT NULL DEFAULT 0, "locked" DECIMAL(36,18) NOT NULL DEFAULT 0, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "asset_balances_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ledger_accounts" ("id" TEXT NOT NULL, "type" "LedgerAccountType" NOT NULL, "assetSymbol" TEXT NOT NULL, "name" TEXT NOT NULL, "bankAccountId" TEXT, "cryptoWalletId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ledger_accounts_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ledger_entries" ("id" TEXT NOT NULL, "ledgerAccountId" TEXT NOT NULL, "groupId" TEXT NOT NULL, "direction" "LedgerDirection" NOT NULL, "assetSymbol" TEXT NOT NULL, "amount" DECIMAL(36,18) NOT NULL, "referenceType" TEXT NOT NULL, "referenceId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ledger_entries_pkey" PRIMARY KEY ("id"));
CREATE TABLE "beneficiaries" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "type" "BeneficiaryType" NOT NULL, "nickname" TEXT NOT NULL, "accountName" TEXT NOT NULL, "accountNumber" TEXT NOT NULL, "bankName" TEXT, "isFavorite" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "beneficiaries_pkey" PRIMARY KEY ("id"));
CREATE TABLE "transfers" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "sourceAccountId" TEXT NOT NULL, "beneficiaryId" TEXT, "currencySymbol" TEXT NOT NULL, "amount" DECIMAL(36,18) NOT NULL, "feeAmount" DECIMAL(36,18) NOT NULL DEFAULT 0, "narration" TEXT, "status" "TransferStatus" NOT NULL DEFAULT 'PENDING', "idempotencyKey" TEXT NOT NULL, "ledgerGroupId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "transfers_pkey" PRIMARY KEY ("id"));
CREATE TABLE "transactions" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "type" "TransactionType" NOT NULL, "direction" "TransactionDirection" NOT NULL, "status" "TransactionStatus" NOT NULL DEFAULT 'PENDING', "assetSymbol" TEXT NOT NULL, "amount" DECIMAL(36,18) NOT NULL, "feeAmount" DECIMAL(36,18) NOT NULL DEFAULT 0, "counterparty" TEXT, "narration" TEXT, "referenceType" TEXT NOT NULL, "referenceId" TEXT NOT NULL, "ledgerGroupId" TEXT, "isDemo" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "transferId" TEXT, CONSTRAINT "transactions_pkey" PRIMARY KEY ("id"));
CREATE TABLE "crypto_orders" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "symbol" TEXT NOT NULL, "side" "OrderSide" NOT NULL, "type" "OrderType" NOT NULL, "quantity" DECIMAL(36,18) NOT NULL, "limitPrice" DECIMAL(36,18), "filledPrice" DECIMAL(36,18), "feeAmount" DECIMAL(36,18) NOT NULL DEFAULT 0, "status" "OrderStatus" NOT NULL DEFAULT 'OPEN', "idempotencyKey" TEXT NOT NULL, "ledgerGroupId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "filledAt" TIMESTAMP(3), "cancelledAt" TIMESTAMP(3), CONSTRAINT "crypto_orders_pkey" PRIMARY KEY ("id"));
CREATE TABLE "conversion_quotes" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "fromAsset" TEXT NOT NULL, "toAsset" TEXT NOT NULL, "fromAmount" DECIMAL(36,18) NOT NULL, "toAmount" DECIMAL(36,18) NOT NULL, "rate" DECIMAL(36,18) NOT NULL, "feeAmount" DECIMAL(36,18) NOT NULL DEFAULT 0, "expiresAt" TIMESTAMP(3) NOT NULL, "consumedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "conversion_quotes_pkey" PRIMARY KEY ("id"));
CREATE TABLE "conversions" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "quoteId" TEXT NOT NULL, "fromAsset" TEXT NOT NULL, "toAsset" TEXT NOT NULL, "fromAmount" DECIMAL(36,18) NOT NULL, "toAmount" DECIMAL(36,18) NOT NULL, "feeAmount" DECIMAL(36,18) NOT NULL DEFAULT 0, "idempotencyKey" TEXT NOT NULL, "ledgerGroupId" TEXT, "status" "TransactionStatus" NOT NULL DEFAULT 'PENDING', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "conversions_pkey" PRIMARY KEY ("id"));
CREATE TABLE "deposits" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "assetSymbol" TEXT NOT NULL, "amount" DECIMAL(36,18) NOT NULL, "network" TEXT, "demoAddress" TEXT, "status" "DepositStatus" NOT NULL DEFAULT 'PENDING', "idempotencyKey" TEXT NOT NULL, "ledgerGroupId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "completedAt" TIMESTAMP(3), CONSTRAINT "deposits_pkey" PRIMARY KEY ("id"));
CREATE TABLE "withdrawals" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "assetSymbol" TEXT NOT NULL, "amount" DECIMAL(36,18) NOT NULL, "feeAmount" DECIMAL(36,18) NOT NULL DEFAULT 0, "destination" TEXT NOT NULL, "network" TEXT, "status" "WithdrawalStatus" NOT NULL DEFAULT 'PENDING', "idempotencyKey" TEXT NOT NULL, "ledgerGroupId" TEXT, "reviewedByAdminId" TEXT, "reviewedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "withdrawals_pkey" PRIMARY KEY ("id"));
CREATE TABLE "cards" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "formFactor" "CardFormFactor" NOT NULL, "maskedNumber" TEXT NOT NULL, "expiryMonth" INTEGER NOT NULL, "expiryYear" INTEGER NOT NULL, "status" "CardStatus" NOT NULL DEFAULT 'ACTIVE', "spendingLimit" DECIMAL(36,18), "currencySymbol" TEXT NOT NULL DEFAULT 'USD', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "cards_pkey" PRIMARY KEY ("id"));
CREATE TABLE "card_transactions" ("id" TEXT NOT NULL, "cardId" TEXT NOT NULL, "merchant" TEXT NOT NULL, "amount" DECIMAL(36,18) NOT NULL, "currencySymbol" TEXT NOT NULL, "status" "TransactionStatus" NOT NULL DEFAULT 'COMPLETED', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "card_transactions_pkey" PRIMARY KEY ("id"));
CREATE TABLE "watchlist_items" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "assetSymbol" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "watchlist_items_pkey" PRIMARY KEY ("id"));
CREATE TABLE "notifications" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "type" "NotificationType" NOT NULL, "title" TEXT NOT NULL, "body" TEXT NOT NULL, "isRead" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "notifications_pkey" PRIMARY KEY ("id"));
CREATE TABLE "audit_logs" ("id" TEXT NOT NULL, "actorUserId" TEXT, "actorRole" "UserRole", "action" TEXT NOT NULL, "targetType" TEXT NOT NULL, "targetId" TEXT NOT NULL, "metadata" JSONB, "ipAddress" TEXT, "userAgent" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "audit_logs_pkey" PRIMARY KEY ("id"));
CREATE TABLE "api_connections" ("id" TEXT NOT NULL, "provider" TEXT NOT NULL, "mode" TEXT NOT NULL DEFAULT 'public', "status" TEXT NOT NULL DEFAULT 'unknown', "lastHealthCheckAt" TIMESTAMP(3), "metadata" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "api_connections_pkey" PRIMARY KEY ("id"));

